/* Solo se carga al abrir index.html con doble clic (file://), donde el navegador
   bloquea las fuentes externas. Contiene las mismas woff2 de fonts/ en base64. */
(function () {
  var css = '@font-face{font-family:"Gloock";font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format("woff2")}' +
    '@font-face{font-family:"Manrope";font-style:normal;font-weight:200 800;font-display:swap;src:url(data:font/woff2;base64,) format("woff2")}';
  var s = document.createElement('style');
  s.textContent = css;
  document.head.appendChild(s);
})();
